import React, { useState, useEffect } from "react";
import axios from "axios";

const App = () => {
  const [transactions, setTransactions] = useState([]);
  const [text, setText] = useState("");
  const [amount, setAmount] = useState("");

  useEffect(() => {
    fetchTransactions();
  }, []); // ✅ Fetch on first load

  const fetchTransactions = async () => {
    try {
      const res = await axios.get("http://localhost:5000/api/transactions");
      console.log("Fetched Transactions:", res.data); // ✅ Debug log
      setTransactions(res.data);
    } catch (error) {
      console.error("Error fetching transactions:", error);
    }
  };

  const addTransaction = async (e) => {
    e.preventDefault();
    if (!text || !amount) {
      alert("Please enter text and amount");
      return;
    }

    try {
      const newTransaction = { text, amount: parseFloat(amount) };
      const res = await axios.post("http://localhost:5000/api/transactions", newTransaction);
      setTransactions([...transactions, res.data]); // ✅ Update state immediately
      setText("");
      setAmount("");
    } catch (error) {
      console.error("Error adding transaction:", error);
    }
  };

  return (
    <div className="container">
      <h2>Income-Expense Manager</h2>
      <ul>
        {transactions.map((transaction) => (
          <li key={transaction._id}>
            {transaction.text} - ₹{transaction.amount}
          </li>
        ))}
      </ul>
      <form onSubmit={addTransaction}>
        <input type="text" value={text} onChange={(e) => setText(e.target.value)} placeholder="Enter text" required />
        <input type="number" value={amount} onChange={(e) => setAmount(e.target.value)} placeholder="Enter amount" required />
        <button type="submit">Add Transaction</button>
      </form>
    </div>
  );
};

export default App;
